  劫煞:{d:()=>`《三命通会》卷三「论劫煞亡神」：${q('sm_jiewang')}。绝是十二长生里最弱的一位。水局的绝在巳，木局在申，火局在亥，金局在寅。`},
  亡神:{d:()=>`《三命通会》卷三「论劫煞亡神」：${q('sm_jiewang')}。临官是十二长生里的第四位。水局的临官在亥，木局在寅，火局在巳，金局在申。`},
