const GJB_K=[['成','成格的条件'],['败','败格的条件'],['带忌','带忌：成格的条件里又带着破它的字'],['救应','救应：败格的条件里又有救它的字']];
/* ges 是要核对的格（一个或者两个）。每个格：各条合不合，四类各合几条，归纳成一个词 v。
   v 的先后是页面的做法：合了救应的归「救应」；否则合了败格或带忌的条件，同时也合成格的（或者只合带忌的）归「带忌」，只合败格的归「败」；
   只合成格的归「成」；一条也不合归「都不合」。xiang 是合了的成格、救应各条里辅佐用神的字，去掉重复的 */
function gjbOf(dm,ps,ges){
  const x=gjCtx(dm,ps);
  const rows=GJB.filter(o=>ges.includes(o.ge)).map(o=>{
    const need=o.need.map(f=>f(x)), ok=need.some(n=>n[1]===false)?false:need.some(n=>n[1]===null)?null:true;
    return Object.assign({},o,{need,ok,more:(o.more||[]).map(([f,qk])=>f(x).concat(qk)),xiang:ok===true&&o.xg?o.xg(x):[]});
  });
  const groups=ges.map(ge=>{
    const rs=rows.filter(r=>r.ge===ge), n=k=>rs.filter(r=>r.k===k&&r.ok===true).length, cnt={成:n('成'),败:n('败'),带忌:n('带忌'),救应:n('救应')};
    const v=cnt.救应?'救应':cnt.败+cnt.带忌?(cnt.成||!cnt.败?'带忌':'败'):cnt.成?'成':'都不合';
    return {ge,rows:rs,cnt,unsure:rs.filter(r=>r.ok===null).length,v};
  });
  const seen={}, xiang=rows.flatMap(r=>r.xiang.map(o=>Object.assign({from:r.id},o))).filter(o=>{const key=o.k+(o.z||'')+o.h;if(seen[key]) return false;seen[key]=1;return true;});
  return {groups,rows,xiang,tier:x.tier};
}
/* 用神变化（「论用神变化」里因会合而变的一半；因透干而变的一半在格局参考里）：月支和另外两个地支凑齐三合局，月令的用神化成这一局的五行。
   full 三支全；from、cat 是月令本气、这一局对日主的关系（0 同我 … 4 生我）；same 两者相同，不变；benTou 月令的本气又透在天干上，
   照书「变而不失本格」；ge 是化出来的格：比肩和劫财归建禄月劫，别的看那一行透出来的天干是什么十神，没有透的看这一局旺支的本气（页面定的）。
   只认三支全的三合，三会、半合不算；旺支被冲的情形书里这一章没有讲，不另算 */
function bianOf(dm,ps){
  const mz=ps[1].z, zs=ps.map(p=>p.z), ju=SANHE.find(x=>x.slice(0,3).includes(mz)), tri=ju.slice(0,3);
  const full=tri.every(z=>zs.includes(z)), half=tri.filter(z=>z!==mz&&zs.includes(z)), to=EL.indexOf(ju[3][0]), ben=HID[mz][0], de=gEl(dm);
  const from=(gEl(ben)-de+5)%5, cat=(to-de+5)%5, tou=[0,1,3].filter(i=>gEl(ps[i].g)===to).map(i=>({k:ps[i].k,i,h:ps[i].g}));
  const gd=godOf(dm,tou.length?tou[0].h:HID[ju[1]][0]), benTou=[0,1,3].some(i=>ps[i].g===ben), hit=full&&cat!==from;
  return {mz,tri:tri.join(''),name:ju[3],full,half,to,ben,from,cat,same:cat===from,tou,god:gd,benTou,hit,ge:hit?(cat===0?'建禄月劫':GE[gd]):null};
}
const bianNow=()=>memo('bian',()=>bianOf(DM,NATAL));
/* 成败救应照哪个格核对：会合让用神变了、月令的本气又没有透出来的，照变出来的格；别的照格局参考归的格 */
function gjbGes(){const b=bianNow(), cur=gjzGe();return b.hit&&!b.benTou&&!cur.includes(b.ge)?{ges:[b.ge],bian:true}:{ges:cur,bian:false};}
const gjbNow=()=>memo('gjb',()=>gjbOf(DM,NATAL,gjbGes().ges));
/* 归纳的词和它后面一句人话。每张盘都给一个结论，后面一句用传统的读法说它是什么（2026-11-18 用户要的：
   「这些格局用人话说代表了什么还是没有解释啊」「希望能看到结果」）。v 是照「论用神成败救应」这一章的条件归的；
   合了成格的条件、书里讲这一格时另外要的条件（more）却不合或者定不了的，结论换成「成欠」，不写成完整的成格，
   并且把是哪一条、欠哪一项接在后面（gjbLimits）。原来不管另外的条件，一律写成格；中间一版只写「有成格条件相符」，没有结论也没有人话 */
const GJB_V={成:'重心有帮手，没有被搅，照这一章这个结构是完整的。',带忌:'重心有帮手，可是也有来搅局的字，照这一章是成中有败。',败:'重心被别的字搅坏了，或者缺了该有的帮手，照这一章这个结构不完整。',
  救应:'有来搅局的字，又有别的字把它管住了，照这一章是败中有成。',都不合:'这一章给这一格列的条件一条也不合，书里没有说这种情形算成还是算败。',
  成欠:'重心有帮手，可是书里讲这一格时另外要的条件没有全合，照书还算不上完整的成格。',
  未定:'这一章给这一格列的条件，没有一条确认合；可是有的条件要看强弱，这张盘强弱居中，定不了，所以还不能说都不合。'};
const GJB_VN={成:'成格',带忌:'成中有败',败:'败格',救应:'败中有救应',都不合:'成败的条件都不合',成欠:'成格的条件合，另外的条件没有全合',未定:'没有一条确认合的，有的还定不了'};
const gjbShort=o=>o.ok===true&&o.more.some(m=>m[1]!==true);      // 这一条合了，书里另外要的条件却有不合或者定不了的
const gjbV=g=>g.v==='成'&&g.rows.some(gjbShort)?'成欠':g.v==='都不合'&&g.unsure?'未定':g.v;      // 一条也没有确认合、可是有的条件强弱居中定不了的，不说「都不合」（2026-11-21 复核报告第 6 条：前半句说有一条定不了，后半句说都不合）
function gjbCaveat(o){
  const no=o.more.filter(m=>m[1]===false).map(m=>m[0]), pending=o.more.filter(m=>m[1]===null).map(m=>m[0]);
  return (no.length?'补充条件不合：'+no.join('、')+'。':'')+(pending.length?'补充条件定不了（强弱居中）：'+pending.join('、')+'。':'')+(o.todo?'书里还有页面没有核对的条件，见这一条的解释。':'');
}
function gjbLimits(g){
  return g.rows.filter(o=>o.ok===true).map(o=>{const t=gjbCaveat(o);return t?'「'+o.t+'」：'+t:'';}).filter(Boolean).join('');
}
/* 成败救应那张表上面的一句话 */
function gjbSay(){
  const r=gjbNow(), g0=gjbGes();
  return (g0.bian?`月令会合成局，用神有变化（见上面「用神变化」一行），下面照${g0.ges[0]}核对。`:'')
    +r.groups.map(g=>`${g.ge}的含义：${GE_HUMAN[g.ge]}<br>照「论用神成败救应」逐条看${g.ge}：成格的条件合 ${g.cnt.成} 条，败格的合 ${g.cnt.败} 条，带忌的合 ${g.cnt.带忌} 条，救应的合 ${g.cnt.救应} 条`+(g.unsure?`，另有 ${g.unsure} 条要看强弱，强弱居中定不了`:'')+`。<b>${GJB_VN[gjbV(g)]}</b>：${GJB_V[gjbV(g)]}${gjbLimits(g)}`).join('<br>');
}
function noteGjb(){
  return '这张表只列这张盘归的那一格。书里的话下面一句是它的含义，点书里的话看解释。每一条照原文落成几项能数的条件，几项全合才算合，没有合的那一项后面标着「不合」。合了的那一条，书里讲这一格时另外要的条件（补充条件）不合或者定不了的，表里和上面那句话都标出来，不算完整的成格。\n'
    +'上面归纳的那一句照书里「成中有败，必是带忌；败中有成，全凭救应」来说；几条同时合的时候书里没有排先后，先后是页面的做法。合了救应的条件，也不等于每一条败格的条件都有救。\n'
    +'查法是页面照原文定的，原文里没有逐字写：只数年、月、时三个天干和四个地支的本气；「盘里有」是透在天干上或者在地支的本气里；「相见」是两样都有，至少一样透出；「被合住」是透出的字被别的天干五合，年干和月干、月干和时干之间才算，日干自己合它不算；分数是十神的能量；身强、身弱照强弱计分。书里断盘还要看字的先后、远近和轻重，页面只照能数的几项走。';
}
/* 点成败救应表里的一条 */
function xGjb(id){
  const r=gjbNow(), o=r.rows.find(x=>x.id===id); if(!o) return null;
  const st=o.ok===null?'定不了':o.ok?'合':'不合', tx=v=>v===null?'定不了（强弱居中）':v?'合':'不合';
  return {t:`${o.ge} · ${GJB_K.find(x=>x[0]===o.k)[1].split('：')[0]} · ${st}`,p:[
    ['含义',GJB_HW[o.id]],
    ['字面的意思',o.w],
    ['这张盘',o.need.map(([l,v])=>`${l}：${tx(v)}`).join('；')+`。${o.need.length>1?'几项全合才算合，':''}这一条${st}。`+(o.xiang.length?`成这一条靠的是${gjzWhere(o.xiang)}，书里把这样的字叫相神`+(gjbShort(o)?'；这一条书里另外的条件没有全合，这几个字只能算相神的候选':'')+'，见上面「相神」一行。':'')],
    ['原文',`《子平真诠》「论用神成败救应」：${qs(o.q)}这一条是其中的「${o.t}」。`],
    o.more.length?['同一格里另外的话',[...new Set(o.more.map(m=>m[2]))].map(qk=>`${q(qk)}，页面落成`+o.more.filter(m=>m[2]===qk).map(([l,v])=>`「${l}」：${tx(v)}`).join('，')).join('；')+'。这几项不算进这一条合不合；其中有不合或者定不了的，表里和上面那句话都标出来。']:null,
    o.todo?['没有核对的',o.todo]:null,
    ['名词',GJ_WORDS+GJ_TERMS]]};      // 怎么查、注意两段每一条都一样，挪到了表下面的说明里（noteGjb），这一格的含义在表上面那句话里
}
/* 「用神变化」一行 */
function bianRow(){
  const b=bianNow(), cur=gjzGe(), F=CAT[b.from][0], T=CAT[b.cat][0];
  const dd=!b.full?`月支${b.mz}没有和别的地支凑齐三合局`+(b.half.length?`（只有${b.mz}、${b.half.join('、')}两支，是半合）`:'')+'，用神不变'
    :b.same?`${b.tri}三合${b.name}，和月令的本气同是${F}，用神不变`
    :b.benTou?`${b.tri}三合${b.name}，月令的${F}化成${T}；本气${b.ben}又透在天干上，照书仍照${cur.join('和')}论`
    :cur.includes(b.ge)?`${b.tri}三合${b.name}，月令的${F}化成${T}，和「格局参考」归的${b.ge}一致`
    :`${b.tri}三合${b.name}，月令的${F}化成${T}，照书改照${b.ge}论`;
  return {k:'用神变化',dd,t:'用神变化',p:[
    ['含义','月令本来代表一样东西；月支和另外两个地支凑成一局以后，可能变成另一样，这张盘的重心也跟着换。'],
    ['两种变法',`《子平真诠》说用神从月令取，可是月令会变。变法有两种：一种是月支的本气不透、别的藏干透了出来，上面「格局参考」一行已经照它走了；一种是月支和另外两个地支凑成三合局，月令就化成这一局的五行。这一行看后一种。`],
    ['典籍',`《子平真诠》「论用神变化」：${q('zp_bian1')}又说${q('zp_bian2')}变了以后好不好，书里分两种：${q('zp_bian4')}。也有变了而不失本格的：${q('zp_bian3')}`],
    ['这张盘',`月支${b.mz}属${b.tri}三合${b.name}。`+(!b.full?(b.half.length?`盘里另有${b.half.join('、')}，只凑了两支，是半合，页面不算变化。`:'另外两支盘里都没有，没有变化。')
      :`三支都在。${b.name}对${DMN}来说是${T}；月令的本气${gN(b.ben)}是${god(b.ben)}，属${F}。`+(b.same?'两者是同一类，用神不变。'
        :`照这一章，月令的${F}化成${T}。`+(b.benTou?`可是本气${b.ben}又透在天干上，照书「变之而不失本格」，仍照${cur.join('和')}论。`
          :cur.includes(b.ge)?`「格局参考」一行照透出来的字归的也是${b.ge}，两处一致。`
          :`${b.tou.length?`${b.name[0]}这一行透在${b.tou.map(o=>`${o.k}干${o.h}`).join('、')}，是${b.god}`:`这一行没有透干，照这一局旺支的本气算是${b.god}`}，归${b.ge}。下面的「成败救应」照${b.ge}核对。`)))],
    ['注意','只认三支全的三合。三会和只有两支的半合，这一章没有举例，页面不算。变了以后是好是坏，书里要通盘看，页面不判。三合局的旺支被冲时还合不合，这一章没有讲，页面照合论。']]};
}
/* 「相神」一行：成败救应表里合了的成格、救应各条，靠哪几个字成的。合了的条目里有书里另外的条件不合或者定不了的，只说是候选 */
function xiangRow(){
  const r=gjbNow(), ge=gjbGes().ges, oks=r.rows.filter(o=>o.ok===true&&o.xiang.length);
  const short=r.rows.some(gjbShort);
  const dd=r.xiang.length?(short?`相神的候选：${gjzWhere(r.xiang)}。合了的那一条，书里另外的条件没有全合，见下表`:`照「论相神紧要」，这张盘的${ge.join('和')}靠这几个字成：${gjzWhere(r.xiang)}`):`「成败救应」里成格、救应的条件一条也没有合，指不出相神`;
  return {k:'相神',dd,t:'相神',p:[
    ['含义',`相神是帮着这一格成立的那个字，好比主角旁边的帮手。《子平真诠》「论相神紧要」：${q('zp_xs')}又举例：${q('zp_xs2')}总起来说：${q('zp_xs3')}`],
    ['这张盘',r.xiang.length?oks.map(o=>`「${o.t}」这一条合，靠的是${gjzWhere(o.xiang)}`+(gjbCaveat(o)?`（${gjbCaveat(o).replace(/。$/,'')}）`:'')).join('；')+'。'+(short?'书里另外的条件没有全合，这几个字只能算相神的候选。':'书里把这样的字叫相神。')
      :`下面「成败救应」里，${ge.join('和')}的成格、救应各条都没有合。书里的相神是成格所靠的那个字，这张盘照这里指不出来。`],
    ['注意',`书里接着说${q('zp_xs4')}相神被合住、被克去，格就败了。相神有没有被伤，页面没有核对。这一行只是把「成败救应」里合了的各条靠的字列出来；书里找相神要通盘看，页面只照能数的条件走。`]]};
}

/* ---------- 顶部信息 ---------- */
function metaRows(){return memo('meta',()=>{
  const c=P.clock, t=P.tst, off=P.dlonSec+P.eotSec, sc=shichen(), lu=P.lunar, yu=P.yun, jy=jiaoyun();
  const [yp,mp,dp,hp]=P.pillars, yz=yp[1], mz=mp[1];
  const mn=s=>Math.round(Math.abs(s)/60);
  const ltxt=`${lu.year}年${lu.leap?'闰':''}${lu.month.replace(/^闰/,'')}月${lu.day}`;
  const animal=z=>ANIMALS[Z.indexOf(z)];
  const pj=P.prevJie, nj=P.nextJie, close=Math.min(pj.min,nj.min)<1440, nearJ=pj.min<nj.min?pj:nj;
  // 真太阳时落在交节的另一边：-1 是还在上一个节之前，1 是已经过了下一个节。年柱、月柱照出生的那一刻排，不照它（见 chart.js 的 chartOf）
  const cmp6=(a,b)=>{for(let i=0;i<6;i++){const d=(a[i]||0)-(b[i]||0);if(d) return d;}return 0;}, side=P.shichen?0:cmp6(t,pj.at)<0?-1:cmp6(t,nj.at)>=0?1:0;
  const xd=xunkong(dp[0],dp[1]), xy=xunkong(yp[0],yp[1]);
  const fallD=NATAL.filter((p,i)=>i!==2&&xd.includes(p.z)).map(p=>`${p.k}支${p.z}`), fallY=NATAL.filter((p,i)=>i!==0&&xy.includes(p.z)).map(p=>`${p.k}支${p.z}`);
  const ty=G[(G.indexOf(mp[0])+1)%10]+Z[(Z.indexOf(mz)+3)%12];
  const about=[yu.y?`${yu.y} 年`:'',yu.m?`${yu.m} 个月`:''].filter(Boolean).join(' ');
  const dl=P.lon-120, cz=P.pillarsClock?P.pillarsClock[3][1]:sc.z;
  // 生在国外、记录的是当地钟表时间的（P.localClock，见 tools/gen_data.py 的 tz，2026-11-17 加外国人示例时加的；P.local 是另一回事，指存在这个浏览器里的人）：
  // 公历一行写当地时间，真太阳时和当地钟表比，经度修正照当地时间的基准经线算（lmt 是当地平太阳时，不用修正），钟表落在哪个时辰也看当地钟表
  const loc=!!P.localClock, L=P.localClock||c, sec=a=>Date.UTC(a[0],a[1]-1,a[2],a[3],a[4],a[5]||0)/1000, lmt=loc&&P.tz==='lmt';
  const offL=loc?sec(t)-sec(L):off, clk=loc?'当地钟表':'北京时间', zone=loc?esc(P.tzName||'当地时间'):'北京时间';
  const zm=loc?(lmt?P.lon:P.tz*15):120, dz=loc?P.lon-zm:dl, dzSec=loc?Math.round(dz*240):P.dlonSec;
  const lonTxt=x=>`${x<0?'西':'东'}经 ${num(Math.abs(x))} 度`;
  const czL=loc?Z[Math.floor(((L[3]+1)%24)/2)]:cz, scL=loc?Object.assign({},sc,{c0:hmOf(sc.h0*3600-offL),c1:hmOf(sc.h1*3600-offL)}):sc;
  const rows=[
    {k:'公历',dd:`${L[0]} 年 ${L[1]} 月 ${L[2]} 日 ${hm(L)}（${loc?'当地时间':P.dst?'北京时间，已减去夏令时的一小时':'北京时间'}）`,t:'公历出生时间',p:[
      ['是什么',loc?`出生地当时的钟表时间，${zone}。${P.source?'出处：'+esc(P.source)+'。':''}换成北京时间是 ${c[0]} 年 ${c[1]} 月 ${c[2]} 日 ${hm(c)}。页面拿这一刻和出生地的经度换算真太阳时，起运也照这一刻算。`
        :(P.source?`${esc(P.source)}上记录的钟表时间。`:'出生时的钟表时间，按北京时间记。')+(P.dst?'出生时在实行夏令时，这里写的是减去一小时以后的北京时间。':'')],
      ['怎么用','排盘就是把它换成四组干支：年柱以立春为界，月柱以节气为界，日柱按六十甲子一天一个往下排，时柱两小时一个时辰。']]},
    {k:'真太阳时',dd:`${t[2]!==L[2]?`${t[1]} 月 ${t[2]} 日 `:''}${hms(t)}，`+(mn(offL)?`比${clk}${slow(offL)}约 ${mn(offL)} 分钟`:`和${clk}相差不到一分钟`),t:'真太阳时',p:[
      ['是什么','按太阳实际位置算出来的当地时间。日柱和时柱照它排，不用钟表时间；年柱和月柱看交节的时刻，见「节气」一行。'],
      ['怎么来的',`${P.place?esc(P.place)+'在':'出生地在'}${lonTxt(P.lon)}，`+(lmt?'当地用的是平太阳时，就是照它自己的经度定的钟表时间，不用做经度修正。'
        :dz?`比${zone}的基准经线（${lonTxt(zm)}）偏${dz<0?'西':'东'} ${num(Math.abs(dz))} 度，每度差 4 分钟，${slow(dzSec)}${dzSec%60?'约 ':' '}${mn(dzSec)} 分钟。`:`正好在${zone}的基准经线上，不用做经度修正。`)
        +`${L[1]} 月${xun(L[2])}，地球公转造成的偏差（均时差）是${slow(P.eotSec)}约 ${mn(P.eotSec)} 分钟。`+(lmt?'':`两项合计${slow(offL)}约 ${mn(offL)} 分钟。`)],
      ['这张盘',`${hm(L)} 换算后是 ${hmNear(t)}，在${sc.z}时（${sc.h0} 点到${sc.h1<sc.h0?'次日 ':' '}${sc.h1} 点）。按${loc?'当地钟表':'钟表时间'}算，这个时辰是 ${scL.c0} 到 ${scL.c1}。`+(czL!==sc.z?`钟表上的 ${hm(L)} 本来落在${czL}时，换算之后进了${sc.z}时，时柱跟着变了。`:'')]]},
    {k:'农历',dd:`${ltxt}，${sc.z}时`,t:'农历日期',p:[
      ['是什么',`出生那一天在农历里的日子：${ltxt}。`],
      ['注意','农历日期不参与排盘，只作对照。月柱看节气，不看农历月份；年柱看立春，不看正月初一。'+(lu.year===yp?'':(gz60(yp[0],yp[1])+1)%60===gz60(lu.year[0],lu.year[1])?`这一天过了正月初一，还没到立春，所以农历年已经是${lu.year}，年柱还是${yp}。`:`这一天过了立春，还没到正月初一，所以年柱已经是${yp}，农历年还是${lu.year}。`)]]},
    {k:'出生地',dd:esc(P.place),t:'出生地',p:[['是什么','出生的地方。排盘只用它的经度来换算真太阳时。']]},
    {k:'生肖 · 星座',dd:`${animal(yz)} · ${P.xingzuo}座`,t:'生肖和星座',p:[
      ['生肖',`就是年支。${yz}对应${animal(yz)}。`+(lu.year!==yp?`年支以立春为界。按正月初一换年的算法，生肖是${animal(lu.year[1])}。两种算法都有人用。`:'')],
      ['星座',`${P.xingzuo}座是西方占星里的太阳星座，和八字是两套互不相干的体系，排盘软件习惯一并列出。`]]},
    {k:'节气',dd:`${pj.name}后 ${rough(pj.min)}，${nj.name}前 ${rough(nj.min)}`,t:'出生节气',p:[
      ['是什么','二十四节气里，立春、惊蛰、清明等十二个节是八字月份的分界。'],
      ['这张盘',`${pj.name}（${pj.at[1]} 月 ${pj.at[2]} 日）到${nj.name}（${nj.at[1]} 月 ${nj.at[2]} 日）之间是${mz}月。出生在${pj.name}之后 ${span(pj.min)}、${nj.name}之前 ${span(nj.min)}`+(close?`。离${nearJ.name}不到一天，${nearJ.name==='立春'?'年柱和月柱':'月柱'}要看交接的具体时刻（北京时间 ${nearJ.at[1]} 月 ${nearJ.at[2]} 日 ${hm(nearJ.at)}）。`+(P.jie?`出生时间只记到时辰，${nearJ.name}正落在${sc.z}时里，这张盘照${nearJ.name}${P.jie==='after'?'之后':'之前'}那一边排，见下面一段。`:P.shichen&&!P.nohour?`出生时间只记到时辰，页面拿${sc.z}时的中点当钟表时间去比。`:'交节是一个确定的时刻，页面拿出生的那一刻去比。'):`，离两头都超过一天，月柱${mp}没有疑问。`)],
      side?['注意',`真太阳时是 ${t[1]} 月 ${t[2]} 日 ${hm(t)}，落在${side<0?pj.name+'之前':nj.name+'之后'}。有的排法直接拿真太阳时去比，会排成${side<0?'上':'下'}一个月。同一个时刻不会因为出生地的经度不同就换了月份，页面照出生的那一刻排，${(side<0?pj:nj).name==='立春'?`年柱${yp}、`:''}月柱${mp}。`]:null,
      // 只知道时辰、交节又落在这个时辰前后的：时辰照当地太阳定，换成北京时间要看经度，出生在交节之前还是之后其实定不了。
      // 原来照中点排了就当确定的写（2026-11-18 审阅）。三小时：时辰本身两小时的一半，加上经度偏西偏东的余量
      P.shichen&&!P.nohour&&nearJ.min<180?['只知道时辰',(()=>{const up=nearJ===nj?1:-1, alt=gz=>JZ(((gz60(gz[0],gz[1])+up)%60+60)%60);
        return `时辰是照当地太阳定的，换成北京时间还要看出生地的经度；这里只知道时辰，不知道是其中的哪一刻。${nearJ.name}离${sc.z}时的中点只有 ${span(Math.floor(Math.abs(secOf(nearJ.at)-secOf(P.clock))/60))}，出生的那一刻在${nearJ.name}之前还是之后，其实定不了。排到${nearJ.name}${up>0?'之后':'之前'}的话，月柱是${alt(mp)}`+(nearJ.name==='立春'?`，年柱是${alt(yp)}，大运的顺逆也跟着变`:'')+(P.jie?`。这张盘的出生信息里另记着是${nearJ.name}${P.jie==='after'?'之后':'之前'}出生的（从八字反查日期的，记的是四柱对得上的那一边），年柱、月柱和大运照这一边排：取${sc.z}时里${nearJ.name}${P.jie==='after'?'之后':'之前'}那一段的中点 ${hm(P.jieClock)} 当出生的时刻，${nearJ.name==='立春'?`年柱${yp}、`:''}月柱${mp}。`:`。页面照中点排，${nearJ.name==='立春'?`年柱${yp}、`:''}月柱${mp}。`);})()]:null]},
    {k:'空亡',dd:`日柱查：${xd} · 年柱查：${xy}`,t:'空亡',p:[
      ['是什么','十个天干配十二个地支，每配完一轮（一旬）会剩下两个地支，这两个叫空亡。'],
      ['怎么来的',`日柱${dp}在甲${Z[xunHead(dp[0],dp[1])]}旬，剩下${xd[0]}、${xd[1]}。年柱${yp}在甲${Z[xunHead(yp[0],yp[1])]}旬，剩下${xy[0]}、${xy[1]}。`],
      ['这张盘',(fallD.length?`${fallD.join('、')}落在日柱的空亡里`:'没有地支落在日柱的空亡里')+'，'+(fallY.length?`${fallY.join('、')}落在年柱的空亡里`:'没有地支落在年柱的空亡里')+'。传统上以日柱查出的为主，落空的地支读作力量打折扣。']]},
    {k:'胎元 · 命宫',dd:`${P.taiyuan}（${DATA.nayin[P.taiyuan]}） · ${P.minggong}（${DATA.nayin[P.minggong]}）`,t:'胎元和命宫',p:[
      ['胎元','推算出来的受孕月份。'+(ty===P.taiyuan?`月干往后一位，月支往后三位：${mp}变成${ty}。`:'')],
      ['命宫','由月支和时支推出来的一个干支，借自更早的星命术。'],
      ['怎么用','两者在子平法里都只是辅助参考，初学可以先放一放。括号里是它们的纳音。']]},
    {k:'身宫',dd:`${P.shengong}（${DATA.nayin[P.shengong]}）`,t:'身宫',p:[
      ['是什么','和命宫是一对，同样由月支和时支推出。'],
      ['怎么用','子平法里很少用到，初学可以先放一放。']]},
    {k:'起运',dd:`出生后${about?'约 '+about:'不到一个月'}，${jy.Y} 年 ${jy.M} 月${xun(jy.D)}`,t:'起运时间',p:[
      ['是什么','第一步大运从什么时候开始。'],
      ['怎么来的',`${yy(yp[0])}年出生的${P.gender?'男':'女'}性，大运${yu.forward?'顺':'逆'}排，从出生时刻往${yu.forward?'后':'回'}数到${yu.forward?'下':'上'}一个节（${yu.jie}），相隔 ${span(yu.gapMin)}。按三天折合一年，${about?'约等于 '+about:'折下来不到一个月'}。`],
      ['这张盘',`${L[0]} 年 ${L[1]} 月出生，${jy.Y} 年 ${jy.M} 月${xun(jy.D)}起运，第一步是${P.dayun[0].gz}。`],
      ['注意',`折算有粗有细：有的只按整天和时辰算，有的按分钟算，起运的日子会差几天。这里按分钟算，${P.shichen?'出生时刻取时辰的中点':loc?'出生时刻照记录的当地时间换算':'出生时刻用钟表时间'}。`]]},
    {k:'交运',dd:jy.before?`每逢尾数是 ${jy.Y%10} 的年份，${jy.M} 月${xun(jy.D)}换大运`:`每逢${jy.ygz[0]}年的 ${jy.M} 月${xun(jy.D)}换大运`,t:'交运',p:[
      ['是什么','每十年换一步大运，换的那个时间点叫交运。'],
      ['这张盘',(jy.before?`${jy.Y} 年 ${jy.M} 月还没过立春，算${jy.ygz}年。之后每逢公历尾数是 ${jy.Y%10} 的年份换运`:`${jy.Y} 年是${jy.ygz}年。之后每逢公历尾数是 ${jy.Y%10} 的年份（都是${jy.ygz[0]}年）换运`)+`：${jy.Y+10}、${jy.Y+20}、${jy.Y+30}。换运在 ${jy.M} 月${xun(jy.D)}，日子由出生时刻推出，和立春不是同一天。`]]}
  ];
  if(c[0]<1900) rows.find(r=>r.k==='节气').p.push(['回推','这里的节气时刻是用现代的天文算法回推的，和当时历书上的时刻可能差几分钟到几十分钟。出生离节气交接很近的盘要留意这一点。']);
  if(P.shichen){                 // 出生时间只记到时辰：没有钟表时间，也就没有换算真太阳时这一步
    const mid=t[3], src=P.source?`出处：${esc(P.source)}。`:'';
    const put=(k,row)=>{rows[rows.findIndex(r=>r.k===k)]=row;};
    put('公历',{k:'公历',dd:`${c[0]} 年 ${c[1]} 月 ${c[2]} 日，${sc.z}时`,t:'公历出生日期',p:[
      ['是什么','出生那一天的公历日期，时间只记到时辰。'+src+'原始的记载如果是农历，这里的公历日期是换算出来的。'],
      ['怎么用','排盘就是把它换成四组干支：年柱以立春为界，月柱以节气为界，日柱按六十甲子一天一个往下排，时柱两小时一个时辰。']]});
    put('真太阳时',{k:'时辰',dd:`${sc.z}时，${sc.h0} 点到${sc.h1<sc.h0?'次日 ':' '}${sc.h1} 点`,t:`时辰 · ${sc.z}时`,p:[
      ['是什么','出生时间只记到时辰，没有钟表时间。一个时辰是两小时，按当地太阳的位置定，相当于这一页别处说的真太阳时，所以不用再做经度和均时差的换算。'],
      ['这张盘',`排盘时取${sc.z}时的中点，${mid?mid+' 点整':'零点'}。时柱只看时辰，不受这个取法影响。起运的日子是按这个中点算的，出生在这个时辰的头上或尾上的话，起运会早或晚五天左右。`+(mid?'':'子时跨着零点。这里取零点，日柱算记载的那一天。')]]});
    put('出生地',{k:'出生地',dd:esc(P.place),t:'出生地',p:[['怎么用',P.nohour?'这里只作参考。时辰不详，时柱按选中的时辰排，不用拿经度来换算。':'这里只作参考。出生时间记的是时辰，不用拿经度来换算。']]});
    if(P.nohour){              // 时辰不详：时柱是按选中的时辰排的，不是记载
      put('公历',{k:'公历',dd:`${c[0]} 年 ${c[1]} 月 ${c[2]} 日，时辰不详`,t:'公历出生日期',p:[
        ['是什么','只知道出生日期，不知道时辰。'],
        ['怎么用','年柱、月柱、日柱由日期定下来；时柱要看时辰，这里先按选中的时辰排，标题下面一排十二个时辰可以换着看。']]});
      put('时辰',{k:'时辰',dd:`不详，现在按${sc.z}时排`,t:'时辰不详',p:[
        ['是什么','不知道出生的时辰。时柱是按标题下面选中的时辰排的，不是记载。'],
        ['怎么看','十二个时辰换着看：年柱、月柱、日柱一般不变，时柱和跟着它的十神、神煞、关系、强弱计分会变。标题下面那一段列出了十二个时辰里哪些结果不一样。']]});
    }
  }
  // 从八字、时辰不详的链接，或者「直接输入八字」来的人没有出生地，这一行就不列，免得只剩一个行名
  return addRows(P.place?rows:rows.filter(r=>r.k!=='出生地'),note('meta'));
});}
/* notes 里可以补几行：{k: 行名, after: 插在哪一行后面, dd: 显示的值, t: 解释的标题, p: 解释的段落}。
   行名和生成的某一行相同时，顶替那一行。 */
function addRows(rows,extra){
  (extra||[]).forEach(r=>{
    const same=rows.findIndex(x=>x.k===r.k);
    if(same>=0){                       // 和生成的行同名：手写的顶替它；手写的没有「典籍」一段时，把生成的那一段留下
      const keep=(rows[same].p||[]).filter(x=>x&&x[0]==='典籍'&&!(r.p||[]).some(y=>y&&y[0]==='典籍'));
      rows[same]=Object.assign({},r,{p:(r.p||[]).slice(0,1).concat(keep,(r.p||[]).slice(1))});
      return;
    }
    const i=rows.findIndex(x=>x.k===r.after);rows.splice(i<0?rows.length:i+1,0,r);
  });
  return rows;
}

/* ---------- 日主一栏 ---------- */
function kvRows(){return memo('kv',()=>{
  const de=gEl(DM), se=(de+4)%5, mz=NATAL[1].z, r=roots(), s=seals(), tg=touGan(), yz=yinYang();
  const noRoot=NATAL.filter(p=>!r.some(x=>x.k===p.k)).map(p=>`${p.k}支${p.z}`);
  const rows=[
    {k:'日主',dd:`<b class="${gCls(DM)}">${DMN}</b>，${yy(DM)}${EL[de]}，生于${mz}月（${SEASON[mz]}）`,t:'日主',p:[
      ['是什么','日柱的天干，代表这张盘的主人，是全盘的原点。'],
      ['这张盘',`${DM}是${yy(DM)}${EL[de]}。`],
      ['典籍',dts(DM)]]},
    {k:'阴阳',dd:`八个字里阳 ${yz.yang} 个，阴 ${yz.yin} 个`+(yz.yang2!==yz.yang?`；地支照本气算，是阳 ${yz.yang2} 个，阴 ${yz.yin2} 个`:''),t:'阴阳',p:[
      ['是什么','天干和地支各分阴阳。这一行只数盘面的八个字里阳的几个、阴的几个。'],
      ['天干',`《渊海子平》讲阳刃时说到十干的阴阳：${q('yh_wuyang')}。这张盘的四个天干：${NATAL.map(p=>`${p.k}干${p.g}是${yy(p.g)}`).join('，')}。`],
      ['地支',`地支照六十甲子的配法分：子、寅、辰、午、申、戌只和阳干相配，算阳；丑、卯、巳、未、酉、亥只和阴干相配，算阴。这张盘的四个地支：${NATAL.map(p=>`${p.k}支${p.z}是${Z.indexOf(p.z)%2?'阴':'阳'}`).join('，')}。合起来阳 ${yz.yang} 个，阴 ${yz.yin} 个。`],
      ['另一种分法','地支也可以照本气的阴阳算，和这一页定十神的办法一致。两种分法在子、午、巳、亥四支上相反：子、午的本气癸、丁是阴，巳、亥的本气丙、壬是阳。'
        +(yz.diff.length?`这张盘的${yz.diff.map(p=>p.k+'支'+p.z).join('、')}在这四支里，照本气算是阳 ${yz.yang2} 个，阴 ${yz.yin2} 个`+(yz.yang2===yz.yang?'，合计和上面一样。':'。'):'这张盘的四个地支都不在这四支里，两种分法数出来一样。')],
      ['注意','阴阳多少只是个数。排盘软件里的阴阳参考是怎么算的，没有读到说明，这一行不一定和它相同。']]},
    {k:'月令',dd:`生于${mz}月（${SEASON[mz]}），${EL[zEl(mz)]}当令；${EL[de]}处在${wxState(de)}的状态，${['旺','相'].includes(wxState(de))?'得令':'失令'}`,t:'月令',p:[
      ['是什么','月令就是月支，代表出生的季节。这个季节当令的五行力量最足，别的五行按和它的关系分成旺、相、休、囚、死。看强弱先看月令。'],
      ['这张盘',`${DMN}生在${mz}月（${SEASON[mz]}），${EL[zEl(mz)]}当令。${EL[de]}处在${wxState(de)}的状态：${STATEX[wxState(de)]}`],
      ['得令',`旺和相算得令，休、囚、死算失令。《千里命稿》讲强弱时说${q('ql_dl')}。这张盘的${EL[de]}处在${wxState(de)}，${['旺','相'].includes(wxState(de))?'得令':'失令'}。`],
      ['注意','这一行把辰、未、戌、丑四个月都算土当令。《千里命稿》只把立春、立夏、立秋、立冬之前的十八天算土当令，下面「强弱参考」一行照它算，两处可能不一样。']]},
    {k:'根',dd:r.length?r.map(x=>`${x.k}支${x.z}中有${gN(x.h)}`).join('，')+(r.length===1?`，是地支里唯一的${EL[de]}`:''):`地支里没有${EL[de]}，日主没有根`,t:'根',p:[
      ['是什么','天干在地支里找到同一五行的藏干，叫通根，也叫有根。有根的天干站得稳，没有根的叫虚浮。'],
      ['这张盘',r.length?`${DMN}的根在${r.map(x=>`${x.k}支${x.z}，${x.z}里藏着${gN(x.h)}`).join('；')}。`+(noRoot.length?`${noRoot.join('、')}里都没有${EL[de]}。`:''):`四个地支里都没有${EL[de]}，${DMN}没有根。`]]},
    {k:'印',dd:s.length?s.map(x=>x.stem?`${x.k}干${gN(x.g)}透出`:`${x.k}支${x.z}中藏${gN(x.h)}`).join('，'):`盘里没有${EL[se]}，日主没有印`,t:'印',p:[
      ['是什么',`生日主的五行。${EL[se]}生${EL[de]}，所以${EL[se]}是${DMN}的印：${[G[se*2],G[se*2+1]].map(g=>`${yy(g)}${EL[se]}${g}是${god(g)}`).join('，')}。`],
      ['这张盘',s.length?s.map(x=>x.stem?`${x.k}干${gN(x.g)}是${god(x.g)}，露在天干上`:`${x.k}支${x.z}里藏的${gN(x.h)}是${god(x.h)}`).join('。')+'。':`盘里没有${EL[se]}，也就没有印。`]]},
    {k:'月令透干',dd:tg,t:'月令透干',p:[
      ['是什么','月支里藏的天干出现在某一柱的天干上，叫透干。藏着的力量露了出来，分量最重。'],
      ['这张盘',tg+'。格局法从月令透出的字来定格局，见「格局」一页的「格局参考」一行。']]},
    qiangruoRow(),
    dafenRow(),
    qsRow(),
    congRow(),
    huaRow(),
    gejuRow(),
    bianRow(),
    xiangRow(),
    tiaohouRow(),
    duizhaoRow()
  ];
  return addRows(rows,note('kv'));
});}

/* 「合化」一行：天干照《千里命稿》外格篇核对化气格，地支照补充篇看三会、三合成不成局（huaOf）。合化成立的字五行能量改记到化神。
   冲、刑、害、破不改分数，书里没有给增减多少，解释里写明 */
function huaRow(){
  const h=huaNow(), g=h.gan, z=h.zhi, P='年月日时', ps=NATAL, at=i=>`${P[i]}干${ps[i].g}`;
  const pairTx=g.pair?`${at(g.pair[0])}和${at(g.pair[1])}紧贴相合`:'';
  const why={因妒而破:'妒合，其情不专',不得月令:`生在${ps[1].z}月，不是化${EL[g.to]}的月份`,因化而破:`另一对${g.ke?g.ke.map(at).join('、'):''}合化成克${EL[g.to]}的一行`,因克而破:'有克化神的字'};
  const gd=!g.has?(g.far?`年干${ps[0].g}和日干${DM}相合，被月柱隔开，只合不化`:'日干没有紧贴相合的天干')
    :g.ok?`${pairTx}，化${EL[g.to]}，两干改记${EL[g.to]}`+(g.more.length?`；成了化气格，${g.more.map(([a,b2,t])=>`${at(a)}、${at(b2)}也化${EL[t]}`).join('，')}`:'')
    :`${pairTx}，${why[g.why]}，不化`;
  const zd=z.ok?`${z.tri}${z.kind==='方合'?'三会':'三合'}${z.name}，这几个地支改记${EL[z.to]}`
    :z.kind==='局合'?`${z.tri}三合${z.name}，旺支${z.wang}被${z.chong}紧贴冲着，作冲不作合`
    :z.half?`只有${z.half}两支，是半合，不改记`:'没有三支全的三合、三会';
  const keTx=(g.keG||[]).map(at).concat((g.keZ||[]).map(i=>`${P[i]}支${ps[i].z}`)).join('、');
  const here=(g.has?`天干：${gd}。`+(g.why==='因克而破'?`克化神的是${keTx}，照书叫因克而破。`:'')+(g.rescue.length?`转败为成：${g.rescue.join('；')}。`:''):`天干：${gd}。`)
    +`地支：${zd}。`+(h.moves.length?`改记以后，五行能量是${[0,1,2,3,4].map(e=>`${EL[e]} ${nlNow().sum[e]} 分`).join('、')}。`:'这张盘没有改记，五行能量照原来的算法。');
  return {k:'合化',dd:`天干：${gd}；地支：${zd}`,t:'合化',p:[
    ['是什么','天干五合、地支三合三会，合成以后可能化成另一种五行，化出来的那一行叫化神。合化成立的字，这一页的五行能量改记到化神，强弱计分、喜用、用神都跟着变。不成立的只合不化，分数照旧。'],
    ['天干',`照《千里命稿》：${q('ql_h1')}，${q('ql_h2')}。要和日干紧贴（月干或时干），生在化神当令的月份（例如${q('ql_h3')}），四柱不见克化神的字。外格篇把这样的盘叫化气格，又列了被克、被妒、被别的合化所克三种破格，和几种转败为成，页面照着核对。成了化气格，${q('ql_h6')}。`],
    ['地支',`照《千里命稿》补充篇：六合${q('ql_z1')}，不改记；三会、三合要三支全，中间${q('ql_z2')}；三会${q('ql_z5')}；三合的${q('ql_z3')}；${q('ql_z4')}。两支里有旺支的半合，书里说力量仅次于三支全，页面不改记。`],
    ['这张盘',here],
    ['冲、刑、害、破',`这四样不改分数，书里没有说增减多少。冲，《千里命稿》只讲谁胜谁负、远近轻重：${q('ql_c1')}；年支和时支相冲${q('ql_c2')}；辰戌丑未相冲${q('ql_c3')}。刑，${q('ql_x1')}；害，${q('ql_x2')}。任铁樵说${q('tc_xing')}，${q('tc_hai')}，${q('tc_po')}。`],
    ['别家',`徐乐吾的评注比《千里命稿》严：${q('zj_h1')}照它，成了化气格，别的天干也不化。`],
    ['注意',`化气格是外格，就是正格以外的特殊格局。《千里命稿》说${q('ql_h4')}，喜忌跟着化神走；「强弱」一页的强弱和「喜忌」一页的扶抑照原来的日干算，遇到化气格只能对照着看。「喜忌」一页的用神照任铁樵《滴天髓阐微》以化神为体，化神有余取泄它的，不足取生它、助它的。分数怎么改是照书里的规则落下来的，书里没有给分数。`]]};
}
/* 「从格」一行：照 congOf 核对真从的条件，列出四柱里帮日主的字。只核对，不替这张盘定是不是从格；喜用仍照扶抑取。 */
function congRow(){
  const c=congNow(), at=x=>x.pos==='干'?`${x.k}干${x.ch}`:`${x.k}支${x.z}里的${x.ch}`, roots=c.roots.map(at).join('、');
  return {k:'从格',
    dd:c.ok?'合：四柱里没有一点比肩、劫财、正印、偏印；照从格的书，喜忌和扶抑相反'
      :`不合：四柱里有 ${c.helps.length} 处比肩、劫财、正印、偏印，`+(c.roots.length?`其中${roots}是日主的根`:'不过日主在地支里没有根'),
    t:'从格',p:[
      ['是什么','日主弱到极点、四柱里又没有帮它的字时，有的书不再扶它，改为顺着盘里最强的一方走，叫从格，现在也常说从弱。照从格，喜忌和扶抑正好相反。这一行只核对书里的条件，看的是有没有帮手，不看分数。'],
      ['这张盘',c.ok?'年、月、时三个天干和四个地支里藏的天干，没有一个是比肩、劫财、正印、偏印，合这一行核对的条件。页面的喜用仍照扶抑取，见「喜忌」一页。'
        :`四柱里帮日主的字：${c.helps.map(x=>`${at(x)}（${god(x.ch)}）`).join('、')}。`+(c.roots.length?`${roots}和日主同类，就是它的根。`:'日主在地支里没有同类的字，也就是没有根。')+'有一处就不合这一行核对的条件。'],
      ['典籍',`《滴天髓》说${q('dts_cong')}，注里讲什么算真从：${q('dts_cong2')}。《三命通会》卷五「弃命从煞」也说${q('smth_cong')}。页面照这两处，天干（不算日主自己）和地支里藏的天干都算，有一处比肩、劫财、正印、偏印就不合。`],
      ['异文',`也有不这么严的说法。《滴天髓》论假从：${q('dts_jiacong')}，就是中间有一点帮手也可以从，只是算假从。怎样算「有所助」，书里没有能照着数的条件，这一行不核对；这里写「不合」的盘，照假从的说法仍可能论作从格。`],
      ['阴干和阳干',`徐乐吾的《子平真诠评注》把阴干、阳干分开讲，先引《滴天髓》${q('zj_c1')}。阳干${q('zj_c2')}；阴干在正财、偏财、正官、七杀偏盛时照样从，${q('zj_c3')}。这张盘的日主${DMN}是${yy(DM)}干。这一行的核对不分阴阳，照的是上面那条最严的条件。`],
      ['注意',`强弱计分只有 25 分、30 分两道线，没有「极弱」一档，也没有给从格的分数线，所以页面不按分数分出极弱、从弱。更细的分档见上面「强弱参考」一行，《千里命稿》把这张盘归${qrName(qrNow())}。日主强到极点的一头也有专旺一类的说法，页面没有核对。`]]};
}
/* 日主一页最上面的四项，照排盘软件里常见的那张小卡片：日主属性、阴阳参考、旺衰参考、格局参考。
   前两项是盘面上的事实，就是「日主」「阴阳」两行。后两项是「强弱」「格局」两页的结论，写明照的是哪本书、哪种算法，点开是那一行的解释。 */
function quadItems(){
  const q0=qrNow(), qs=qsNow(), g=geju(), yz=yinYang(), de=gEl(DM), mz=NATAL[1].z;
  const cls=g.kind==='阳刃'?'阳刃':'建禄月劫';
  // 每一项：k 名目，x 点开的解释，big 大字，sub 下面一行小字。旺衰参考两种办法各占一行，大字后面用小字写明是哪一种
  return [
    {k:'日主属性',x:'kv|日主',big:`<span class="${gCls(DM)}">${DMN}</span>`,sub:`${yy(DM)}${EL[de]}，生于${mz}月（${SEASON[mz]}）`},
    {k:'阴阳参考',x:'kv|阴阳',big:`阳 ${yz.yang} · 阴 ${yz.yin}`,sub:yz.yang2!==yz.yang?`盘面八个字，地支子寅辰午申戌为阳；照本气算是阳 ${yz.yang2} · 阴 ${yz.yin2}`:'盘面八个字，地支子寅辰午申戌为阳'},
    {k:'旺衰参考',x:'kv|强弱参考',lines:true,big:`<span class="ln cx" data-x="kv|强弱参考" role="button" tabindex="0">${q0.tier==='中'?'中强（中弱）':q0.tier}<em>《千里命稿》</em></span><span class="ln cx" data-x="kv|强弱计分" role="button" tabindex="0">${({强:'身强',弱:'身弱',间:'强弱居中'})[qs.tier]}<em>强弱计分 ${qs.help} 分</em></span>`,sub:'两种办法并列，详见「强弱」一页'},
    {k:'格局参考',x:'kv|格局参考',big:g.list?gejuNames(g).join('、'):`${cls}一类`,
      sub:g.list?'照《子平真诠》':gEl(g.ben)!==gEl(DM)?'照《子平真诠》；也可能归印格，书里没有定说':'照《子平真诠》；用神要在别处另取'}];
}
/* 宫位一栏：按年、月、日、时四柱各列一栏，只列事实。每一柱：配谁；天干和藏干各是什么十神；六亲表里配在这一柱的亲属看哪个十神、
   那个十神在不在这一柱（日柱只看日支，因为配偶配的是日支）；它和另外三柱之间的合冲刑害（就是原局的那些关系，按柱分开）；十二长生；
   落没落在日柱、年柱查出的空亡里；它在五行能量里占几分。 */
function gwCols(){
  const base=relations(NATAL), kin=liuqinRows(), xk=xunkong(NATAL[2].g,NATAL[2].z), xkY=xunkong(NATAL[0].g,NATAL[0].z), de=gEl(DM), se=(de+4)%5;
  const WHO={年:'祖上',月:'父母。《渊海子平》把伯叔、兄弟也放在这里',日:'日干是自己，日支是配偶',时:'子女'};
  return NATAL.map((p,i)=>{
    const hs=HID[p.z].split(''), its=nlNow().items.filter(x=>x.i===i), sum=nlSum(its), total=sum.reduce((a,b)=>a+b,0), help=sum[de]+sum[se];      // its 是合化改记过的
    const rel=[];
    base.forEach(r=>r.inst.forEach(ks=>{if(ks.includes(p.k)) rel.push({key:['rel',r.t,r.c,r.n,r.where.join('、'),r.top,r.grp].join('|'),t:r.t,n:r.n,others:ks.filter(k=>k!==p.k).map(k=>k+(r.grp==='g'?'干':'支'))});}));
    const falls=[];
    if(p.k!=='日'&&xk.includes(p.z)) falls.push(`日柱查出的${xk}`);
    if(p.k!=='年'&&xkY.includes(p.z)) falls.push(`年柱查出的${xkY}`);
    return {k:p.k,g:p.g,z:p.z,day:!!p.day,who:WHO[p.k],god:p.day?'日主':god(p.g),hid:hs.map(h=>[h,god(h)]),
      kin:kin.filter(r=>r.gong[0]===p.k).map(r=>({who:r.who,god:r.god,at:(p.k!=='日'&&god(p.g)===r.god?[`${p.k}干${p.g}`]:[]).concat(hs.filter(h=>god(h)===r.god).map(h=>`${p.k}支${p.z}里的${h}`))})),
      rel,zz:stage(p.g,p.z),st:stage(DM,p.z),xk:falls.length?`${p.z}落在${falls.join('和')}里`:`${p.z}没有落空`,
      nl:{total,sum,help,rest:total-help}};
  });
}
/* 宫位：四柱各配哪一类亲属。plain 先用一句白话说这一柱配谁，src 是几部书的原文。 */
function gongwei(k){
  const mine={年:'年柱配祖上。',月:'月柱配父母，《渊海子平》把伯叔、兄弟也放在这里。',日:'日柱配自己和配偶：日干是自己，日支紧挨着日主，通常叫配偶宫。',时:'时柱配子女。'}[k];
  const two=`《渊海子平》说${q('gw')}《子平真诠》说${q('zp_gf')}`+(k==='时'?'《渊海子平》那一句没有说到时柱，时柱配子女是照《子平真诠》的顺序。':'');
  return {plain:'四柱各配一类亲属，叫宫位。'+mine+'宫位是分类的办法，不能据此说这张盘的主人和哪位亲属怎样。',
    src:two+`近代的《千里命稿》列了两种看法：一种${q('ql_gong1')}、月为父母，一种${q('ql_gong2')}、月为兄弟姊妹；两种都以日支为配偶、时为子女。`+`《渊海子平》还拿植物打比方，说${q('gmhg')}。后来有把四柱配到人生早、中、晚几个阶段的说法，各家划的岁数不一样，这一页没有找到它在典籍里的出处。`};
}

/* ---------- 细盘的行名和列名 ---------- */
function rowX(name){
  const N=NATAL, K=p=>p.k;
  if(name==='十神') return {t:'十神',p:[['是什么',`每一柱的天干相对于日主${DMN}是什么，一共十种叫法，合称十神。地支的十神看藏干一行里的小字。排盘软件里这一行常叫主星。`],['这张盘',N.filter(p=>!p.day).map(p=>`${K(p)}干${p.g}是${god(p.g)}`).join('，')+'。日干就是日主自己。'],['怎么读','天干露在外面，传统上说它主看得见的一面；藏在地支里的十神主内里。点任意一个天干，可以看它的十神是怎么推出来的。']]};
  if(name==='天干') return {t:'天干',p:[['是什么','甲乙丙丁戊己庚辛壬癸，共十个。两个一组配五行：甲乙木、丙丁火、戊己土、庚辛金、壬癸水。每组前一个为阳，后一个为阴。'],['颜色和图标','绿是木，红是火，棕是土，金黄是金，蓝是水。大字右上角的小图标也是五行：嫩芽是木，火苗是火，山是土，铜钱是金，水滴是水。'],['典籍',`《滴天髓》说${q('dts_yy')}：十个天干里，丙火最阳，癸水最阴。`]]};
  if(name==='地支') return {t:'地支',p:[['是什么','子丑寅卯辰巳午未申酉戌亥，共十二个，对应十二个月、十二个时辰，也就是十二生肖。'],['怎么读','地支本身不直接定十神，要看它里面藏的天干。地支之间的合、冲、刑、害见下面的干支关系。'],['颜色和图标','颜色和右上角的图标是这个地支的五行。右下角的小字是它的生肖，屏幕窄的时候不显示。']]};
  if(name==='藏干') return {t:'藏干',p:[['是什么','每个地支里藏着一到三个天干。排在第一个的是本气，是主要成分；后面的是次要成分。'],['怎么读','地支的十神按本气算。次要成分力量小，但大运、流年把它引出来时也会起作用。'],['这张盘',N.map(p=>`${K(p)}支${p.z}藏${HID[p.z].split('').join('、')}`).join('，')+`，共${cn(natalHidden().length)}个。`]]};
  if(name==='星运'){
    const good=N.filter(p=>['长生','临官','帝旺'].includes(stage(DM,p.z))).map(p=>`${K(p)}支${p.z}`);
    return {t:'星运',p:[['是什么',`日主${DMN}走到每一柱的地支时，处在十二长生的哪个阶段。十二长生把一个五行的兴衰比作人的一生：长生、沐浴、冠带、临官、帝旺、衰、病、死、墓、绝、胎、养。`],['这张盘',N.map(p=>`${K(p)}支${p.z}是${stage(DM,p.z)}`).join('，')+`。按长生、临官、帝旺算得力来看，${DMN}${good.length?'在'+good.join('、')+'上得力':'在四个地支上都不算得力'}。`],['注意','阴干的十二长生是不是倒着走，各派有分歧。这里按通行的阳干顺行、阴干逆行。'],['典籍',`《子平真诠》主张阳顺阴逆，理由是${q('zp_sn')}`]]};
  }
  if(name==='自坐') return {t:'自坐',p:[['是什么','每一柱自己的天干，坐在自己地支上的十二长生状态。看的是这个天干脚下稳不稳。'],['这张盘',N.map(p=>`${K(p)}柱${p.g}坐${p.z}是${stage(p.g,p.z)}`).join('，')+'。'],['注意','这一行受阴干逆行的争议影响最大。比如乙坐亥按表是死，可是亥水生木，亥里还藏着甲木，乙木其实有依靠。只作参考。']]};
  if(name==='空亡'){
    const xd=xunkong(N[2].g,N[2].z), xy=xunkong(N[0].g,N[0].z);
    const fd=N.filter((p,i)=>i!==2&&xd.includes(p.z)).map(p=>`${K(p)}支${p.z}`), fy=N.filter((p,i)=>i!==0&&xy.includes(p.z)).map(p=>`${K(p)}支${p.z}`);
    return {t:'空亡',p:[['是什么','十个天干配十二个地支，每配完一轮（一旬）会剩下两个地支，这两个叫空亡，也叫旬空。'],['这一行','每一柱各自所在的那一旬剩下的两个地支。'],['怎么用',`通常只用日柱那一格：${xd[0]}、${xd[1]}。${fd.length?fd.join('、')+'落在里面'+(fd.length===1?`，叫${fd[0][0]}支空亡`:''):'另外三柱的地支都不在里面'}。有的也参考年柱那一格：${xy[0]}、${xy[1]}，${fy.length?fy.join('、')+'落在里面':'另外三柱的地支都不在里面'}。落空的地支，传统上读作力量打折扣。`]]};
  }
  if(name==='纳音'){
    const ny=p=>DATA.nayin[p.g+p.z];
    return {t:'纳音',p:[['是什么','六十甲子每两个一组，配一个带意象的五行名，比如山头火、大驿土，共三十种。它来自古代音律，属于比子平法更早的算命体系。'],['这张盘',N.map(p=>`${K(p)}柱${ny(p)}`).join('，')+`。常说的什么命，指的是年柱纳音：${ny(N[0])}命。`],['怎么用','子平法基本不用纳音做判断，它主要留在合婚、起名一类的民俗里。']]};
  }
  if(name==='神煞'){
    const mixed=SHENSHA.map((row,i)=>({i,ji:row.filter(o=>SS[o.n].k==='吉').map(o=>o.n),xi:row.filter(o=>SS[o.n].k==='凶').map(o=>o.n)})).filter(x=>x.ji.length&&x.xi.length).sort((a,b)=>Math.min(b.ji.length,b.xi.length)-Math.min(a.ji.length,a.xi.length)||(b.ji.length+b.xi.length)-(a.ji.length+a.xi.length))[0];
    const total=SHENSHA.reduce((n,row)=>n+row.length,0);
    return {t:'神煞',p:[
      ['是什么','按固定口诀从干支里查出来的标签。名字好听的叫神，难听的叫煞。它们是早期算命术留下的，子平法兴起以后退到了次要位置。'],
      ['怎么读','每个口诀只看一两个字，所以每个标签都很常见，单独拿出来下判断没有意义。点具体的名字，可以看它的口诀和有多常见。'],
      ['这张盘',`四柱一共查出 ${total} 个标签。`+(mixed?`${'年月日时'[mixed.i]}柱同时带着${mixed.ji.join('、')}这${cn(mixed.ji.length)}个旧说算吉的，和${mixed.xi.join('、')}这${cn(mixed.xi.length)}个旧说算凶的。吉凶互相打架，是因为每个口诀各查各的。`:'')],
      ['典籍',`神煞在各部书里的分量很不一样。《三命通会》《协纪辨方书》《星学大成》逐条记着它们的取法，这一页的口诀出处写在每个神煞自己的说明里；有五条在典籍里没有找到，也照实写明了。《子平真诠》却专有一章说星辰和格局无关：${q('zp_xc')}`],
      ['前四列','流日、流月、流年、大运这四列的神煞，是拿它们的干支去对原局的年柱、月支和日柱查出来的，查法和原局四柱相同。只看原局自己的那几条不适用：天赦日、三奇贵人、四废日、阴差阳错、魁罡、孤鸾煞、十恶大败、金神、天转、地转、十灵日、六秀日、八专、九丑、童子煞、拱禄。'],
      ['范围',`这一页查 ${SS_NAMES.length} 个：${SS_NAMES.join('、')}。前 ${SS_NAMES.length-SS_EXTRA.length} 个的名单和查法照排盘软件问真八字，${SS_EXTRA.join('、')}三个照典籍。别的书和软件里还有别的神煞，这里没列出来不等于盘里没有。`],
      ['统计','有多常见的数字，是用同样的口诀把 1924 到 2043 年的每一天、每个时辰都排了一遍数出来的，共 52 万多张盘，只算原局四柱。']]};
  }
  return null;
}
function colX(k){
  const i='年月日时'.indexOf(k);
  if(i>=0){
    const p=NATAL[i], [yp,mp,dp,hp]=P.pillars, h=HID[p.z][0];
    const basic=`${gN(p.g)}是${god(p.g)}，${zN(p.z)}的本气${h}是${god(h)}。`;
    if(k==='年') return {t:`年柱 · ${yp}`,p:[['是什么','出生那一年的干支。以立春为界，不看正月初一。'],['宫位',gongwei('年').plain],['宫位的出处',gongwei('年').src],['这张盘',basic]]};
    if(k==='月'){
      const ys=G.indexOf(yp[0]), mi=(Z.indexOf(p.z)+10)%12, ok=G[((ys%5)*2+2+mi)%10]+p.z===mp;
      return {t:`月柱 · ${mp}`,p:[['是什么','出生那个月的干支，以节气为界。'+(ok?`月干由年干推出：${yp[0]}年的正月从${G[((ys%5)*2+2)%10]}寅起，`+(mi?`排到${MONTHS[mi]}是${mp}。`:`正月就是${mp}。`):'')],['为什么重要','月支叫月令，代表出生的季节，是衡量全盘每个字强弱的基准。《滴天髓》说'+q('dts_yl')+'，把月令比作一个人住的宅子。'],['宫位',gongwei('月').plain],['宫位的出处',gongwei('月').src],['这张盘',basic+touGan()+'。']]};
    }
    if(k==='日'){
      const rt=roots().filter(x=>x.k==='日');
      return {t:`日柱 · ${dp}`,p:[['是什么','出生那天的干支。六十甲子一天一个，连续循环，和年、月无关。'],['宫位',gongwei('日').plain],['宫位的出处',gongwei('日').src],['这张盘',`${DMN}坐在${zN(p.z)}上。${p.z}的本气${gN(h)}是${god(h)}。`+(rt.length?`${DMN}在这里有根。`:`${p.z}里没有${EL[gEl(DM)]}，${DMN}在自己坐的这一支上没有根。`)]]};
    }
    const sc=shichen(), hi=Z.indexOf(p.z), late=P.tst[3]===23, base=late?G[(G.indexOf(DM)+1)%10]:DM, bi=G.indexOf(base);
    const ok=G[((bi%5)*2+hi)%10]+p.z===hp;
    return {t:`时柱 · ${hp}`,p:[
      ['是什么','出生时辰的干支，两小时一个时辰。'+(!ok?'':late?`时干由日干推出。晚上 11 点以后出生，这里按第二天的日干${base}来推：${base}日的子时是${hp}。`:`时干由日干推出：${DM}日的子时从${G[(bi%5)*2]}子起，`+(hi?`排到${p.z}时是${hp}。`:`子时就是${hp}。`))],
      ['宫位',gongwei('时').plain],['宫位的出处',gongwei('时').src],
      ['这张盘',basic],
      P.nohour?['注意',`这张盘的时辰不详，时柱是按标题下面选中的${p.z}时排的，换一个时辰就变。`]:
      P.shichen?['注意',`时柱取决于时辰记得准不准。${P.source?'出处：'+esc(P.source)+'。':''}这里按${p.z}时来排。`]:
      ['注意',`时柱取决于出生时间准不准。`+(P.localClock?`当地时间是 ${hm(P.localClock)}，换算成真太阳时是 ${hmNear(P.tst)}，在${p.z}时；这个时辰对应的钟表时间见顶部「真太阳时」一行。`:`钟表时间是 ${hm(P.clock)}，换算成真太阳时是 ${hmNear(P.tst)}，在${p.z}时。按钟表时间算，这个时辰是 ${sc.c0} 到 ${sc.c1}，出了这个范围时柱就会变。`)+(P.source?`出处：${esc(P.source)}。`:'')+(hi===0?'子时跨着零点。这里以零点换日：晚上 11 点到零点出生的，日柱算当天，时干按第二天的日干来推。也有人主张晚上 11 点就换日。':'')]]};
  }
  const d=P.dayun[sel.dy];
  if(k==='大运') return {t:`大运 · ${d.gz}（${d.y0}–${d.y1}）`,p:[
    ['是什么',`十年一步的大环境。它从月柱推出来：阳年出生的男性和阴年出生的女性顺着排，阴年出生的男性和阳年出生的女性倒着排。${yunWhy(4)}。`],
    ['怎么读',`把它当成临时加进盘里的一柱，先看它是${DMN}的什么十神，再看它和原局的字有什么合冲。`],
    ['这一步',`${d.gz[0]}是${god(d.gz[0])}，${d.gz[1]}的本气${HID[d.gz[1]][0]}是${godZ(d.gz[1])}。`],
    ['注意','大运的天干和地支，有的流派说各管五年，有的说十年合看、以地支为重。']]};
  if(k==='流年'){const gz=yearGZ(sel.y);return {t:`流年 · ${sel.y} ${gz}`,p:[
    ['是什么','那一年本身的干支，以立春为界，所有人都一样。'],
    ['怎么读','和大运一样，当成临时加进来的一柱。传统上说大运是十年的背景，流年是当年的主题。'],
    ['这一年',`${gz[0]}是${god(gz[0])}，${gz[1]}的本气${HID[gz[1]][0]}是${godZ(gz[1])}。`]]};}
  if(k==='流月'){const gz=monthGZ(sel.y,sel.m);return {t:`流月 · ${gz}（${JIE[sel.m]} ${jieMD(sel.y)[sel.m]} 起）`,p:[
    ['是什么','那个月本身的干支，以节气为界，所有人都一样。'],
    ['怎么读','和大运、流年一样，当成临时加进来的一柱。传统上说它的分量比流年轻。'],
    ['这个月',`${gz[0]}是${god(gz[0])}，${gz[1]}的本气${HID[gz[1]][0]}是${godZ(gz[1])}。`]]};}
  if(k==='流日'){const gz=dayGZ(sel.d);return {t:`流日 · ${gz}（${new Date(sel.d).getUTCFullYear()} 年 ${mdText(sel.d)}）`,p:[
    ['是什么','那一天本身的干支，六十甲子一天一个，所有人都一样。这里按公历日期排，以零点为界。'],
    ['怎么读','同样当成临时加进来的一柱，是四层里分量最轻的。'],
    ['这一天',`${gz[0]}是${god(gz[0])}，${gz[1]}的本气${HID[gz[1]][0]}是${godZ(gz[1])}。`]]};}
  return null;
}

/* ---------- 各版块的解读框 ---------- */
const box=(title,body)=>`<p class="rd-h">${title}</p>${body}`;
const lis=a=>a.filter(Boolean).map(x=>`<li>${x}</li>`).join('');
function readBz(){
  const mg=NATAL[1].g, c=catCounts(), max=Math.max(...c), top=CAT.filter((_,i)=>c[i]===max);
  const help=whereGod(g=>rel(g)===4), same=whereGod(g=>rel(g)===0), de=gEl(DM);
  return box('解读 · 这张表怎么读',`<ol class="cols">${lis([
    `先找日柱的天干<b class="${gCls(DM)}">${DM}</b>。它叫日主，代表这张盘的主人。其余七个字，都要先换算成它是${DMN}的什么。`,
    `换算的结果叫十神，就是十神一行和藏干旁边的小字。例如月干${gN(mg)}：${stemWhy(mg)}`,
    `数一数十神，按五类来分：${CAT.map((x,i)=>`${x[0]} ${c[i]} 处`).join('，')}。`+(top.length===1?`最多的是${top[0][0]}，传统上读作${top[0][2]}。`:`最多的是${top.map(x=>x[0]).join('、')}，各 ${max} 处。`)+'个数多只说明这一类的字多，不等于它的力量一定大。',
    `再看谁在帮日主。生${DMN}的${EL[(de+4)%5]}`+(help.length?`有 ${help.length} 处：${help.join('、')}。`:'一处也没有。')+`和它同类的${EL[de]}`+(same.length?`有 ${same.length} 处：${same.join('、')}。`:'，除了日主自己一处也没有。')+`消耗它的字，也就是它所生、所克和克它的，有 ${c[1]+c[2]+c[3]} 处。数个数是最粗的办法，强弱还要看月令和根，各派的算法也不一样。`,
    '星运、自坐、空亡、纳音、神煞是附加的标注，越往下越次要。点行名可以看每一行是什么，点格子可以看这一格是怎么来的。'])}</ol>`);
}
/* 四柱细盘一页的解读：后四列就是八字一页，这里只讲前四列 */
function readPan(){
  return box('解读 · 这张表怎么读',`<ul class="cols">${lis([
    '后四列就是「八字」一页的四柱，怎么读见那一页的解读。',
    `前四列是上面选中的流日、流月、流年和大运。读法和原局一样：先看天干和藏干是${DMN}的什么十神，再看它们和原局的字有什么合、冲、刑、害，见「干支关系」一页。`,
    '前四列的神煞，是拿那一柱的干支去对原局的年柱、月支、日柱查出来的，所以同一个干支落在不同的盘里，查出来的神煞不一样。'])}</ul>`);
}
function readYun(){
  return box('解读 · 现在选中的四层',
    `<div class="cols"><p>大运从月柱推出来，十年一步。${yunWhy(3)}。流年、流月、流日是那一年、那个月、那一天本身的干支，所有人都一样。读法相同：把选中的干支当成临时加进盘里的一柱，先看它是${DMN}的什么十神，再看它和原局的字有什么合冲。</p>`+
    `<p>下面每一层后面都说它对${DMN}是加力还是减力：生身、帮身是加力，泄身、耗身、克身是减力。加力减力本身不分好坏。`+(xiNow().lean?`这张盘强弱居中，喜用照用神取，是${elNames(xiNow().xi)}。`:`照扶抑，这张盘喜${elNames(xiNow().xi)}。`)+'每一层后面也写了它的 13 分里算进选择器小卡底下那条的有几分，照哪一种看法算见选择器上面的按钮。'+'</p></div>'+
    '<dl class="layers" id="layers"></dl>'+
    '<p>传统上说大运是十年的背景，流年是当年的主题，流月和流日一层比一层细，分量也一层比一层轻。大运的天干和地支，有的流派说各管五年，有的说十年合看、以地支为重。</p>');
}
function noteYun(){
  const [Y,M,D]=P.yun.start;
  return `流年以立春为界，流月以节气为界，日期是每个月开始的那一天，交节那天整天算新的一个月。换到别的年份时，流月保持原来选中的位置。流日按公历日期排，以零点为界；也有人主张晚上 11 点就换日。\n${Y} 年 ${M} 月 ${D} 日起运，往后每十年的这一天换一步大运；选择器按整年排，交运那一年里这一天以前的日子还在上一步。岁数为虚岁，${P.clock[0]} 年算 1 岁。`;
}
/* 选中的流日实际在不在选中的那一步大运里（ui.js 的 dyAt）。在，就是空的；不在，说一句，放在选择器下面（#note-dy）。
   2026-11-17 内容审阅 C2：选到交运以前的日子，细盘照样排着这一步大运，原来没有说明 */
function dyNote(){
  const a=dyAt(sel.d), dt=t=>{const x=new Date(t);return `${x.getUTCFullYear()} 年 ${x.getUTCMonth()+1} 月 ${x.getUTCDate()} 日`;};
  if(a===sel.dy) return '';
  const day=dt(sel.d), me=P.dayun[sel.dy].gz, tail=`下面各页的大运一列仍是选中的${me}运。`;
  if(a<0) return `选中的 ${day}还没有起运，${dt(dyStart(0))}才交第一步${P.dayun[0].gz}运。${tail}`;
  if(a>=P.dayun.length) return `选中的 ${day}已经过了这里排的八步大运。${tail}`;
  return a<sel.dy?`选中的 ${day}还在上一步${P.dayun[a].gz}运里，${dt(dyStart(sel.dy))}才交${me}运。${tail}`
    :`选中的 ${day}已经交了下一步${P.dayun[a].gz}运（${dt(dyStart(a))}交运）。${tail}`;
}
/* 原局两柱隔得多远：w 形如「年支–日支」 */
function gapText(w){
  const ks=w.split('–'); if(ks.length!==2) return `在${ks.join('、')}之间。`;
  const gap=Math.abs('年月日时'.indexOf(ks[0][0])-'年月日时'.indexOf(ks[1][0]));
  return `在${ks[0]}和${ks[1]}之间，`+['','两柱相邻，力量是足的。','中间隔着一柱，力量打了折扣。','隔了两柱，力量很小。'][gap];
}
function readRel(){
  const base=relations(NATAL), n=base.length;
  if(!n) return box('解读 · 原局的关系','<p>原局四柱之间，没有查到五合、相冲、相克，也没有合、会、刑、害、破。没有关系不算好也不算坏，只说明这八个字之间各管各的。</p>');
  const zr=base.filter(r=>r.grp==='z'), li=[];
  const cnt={}; zr.forEach(r=>new Set(r.where.flatMap(w=>w.split('–'))).forEach(k=>{cnt[k]=(cnt[k]||0)+1;}));
  const ks=Object.keys(cnt).sort((a,b)=>cnt[b]-cnt[a]);
  if(ks.length&&cnt[ks[0]]>=3&&(ks.length<2||cnt[ks[1]]<cnt[ks[0]])){
    const p=NATAL.find(x=>x.k===ks[0][0]), rt=roots(), mine=rt.filter(x=>x.k===p.k);
    li.push(`<b>${ks[0]}${p.z}牵涉最多。</b>${zr.length} 条地支关系里有 ${cnt[ks[0]]} 条和它有关。`+(mine.length?`${p.z}里的${gN(mine[0].h)}又是日主${DMN}在地支里${rt.length===1?'唯一的根':'的一处根'}。`:''));
  }
  base.filter(r=>r.grp==='g').forEach(r=>{
    const [a,b]=r.c.split(''), ke=(gEl(a)+2)%5===gEl(b)?[a,b]:[b,a];
    // 同一对字在原局有两处时，落在日干上的那一处是日主，另一处同一个字是比肩，两处分开说
    const gd=(g,w)=>g===DM&&w.includes('日干')?'日主':god(g), say=w=>r.t==='五合'?`${gd(a,w)}和${gd(b,w)}`:`${gd(ke[0],w)}克${gd(ke[1],w)}`;
    const one=new Set(r.where.map(say)).size===1, each=r.where.map(w=>`${w.replace('–','和')}是${say(w)}`).join('，');
    li.push(`<b>${r.c}${r.t==='五合'?'相合':r.t}。</b>`+(r.t==='五合'?`${one?say(r.where[0])+'合在一起':each+'，都合在一起'}，旧说${r.n}。`:`${gN(ke[0])}克${gN(ke[1])}，也就是${one?say(r.where[0]):each}。`)+r.where.map(gapText).join(''));
  });
  const seen=new Set();
  zr.forEach(r=>{
    if(seen.has(r.c)) return; seen.add(r.c);
    const grp=zr.filter(x=>x.c===r.c), where=r.where.map(gapText).join('');
    if(grp.length>1){li.push(`<b>${r.c}，一对字有${cn(grp.length)}种关系。</b>同时是${grp.map(x=>x.t).join('、')}。${where}`);return;}
    let s=`<b>${r.c}${r.t}。</b>`;
    if(r.t==='拱合'||r.t==='拱会'){const x=r.n[1], b=bringers(x);s+=`${r.n}。两头在、中间空，只算有这个趋势。等大运或流年把${x}带来，局才凑齐`+(b.length?`，比如 ${b.join('、')}。`:'。');}
    else if(r.t==='六合') s+=`旧说${r.n}。`;
    else if(r.t==='半合') s+=`${r.n}的一半，带着中间的旺支。`;
    else if(r.t==='三合'||r.t==='三会') s+=`${r.n}，三个字凑齐了。`;
    else if(r.n) s+=`${r.n}。`;
    li.push(s+where);
  });
  return box(`解读 · 原局的${cn(n)}条关系`,`<ul class="cols">${lis(li)}</ul>`);
}
function readRel2(){
  return box('解读 · 这些关系怎么读',
    '<div class="cols"><p>点任意一条，可以看它的来历和涉及的十神。读的时候先按力量排个序：一般的说法是三会、三合成了局的力量最大，相冲其次，再往下是六合、相刑，相害和相破最小。相邻的强，隔得远的弱。各派的排法略有不同。</p>'+
    '<p>宫位（年柱祖辈、月柱父母、日支配偶、时柱子女）只是分类的习惯。同一年同一个月出生的人，年柱和月柱完全一样，流年对这两柱的冲、刑、害，对他们每个人都相同。所以这一页只说明干支之间的结构，不把它翻成具体的人和事。</p></div>');
}
function readWx(){
  const {cnt,face,n}=wxCounts(), de=gEl(DM), me=zEl(NATAL[1].z);
  const lst=a=>[0,1,2,3,4].sort((x,y)=>a[y]-a[x]||x-y).map(i=>`${EL[i]} ${a[i]}`).join('、');
  const max=Math.max(...cnt), tops=[0,1,2,3,4].filter(i=>cnt[i]===max), help=cnt[de]+cnt[(de+4)%5];
  return box('解读',`<ul class="cols">${lis([
    `三种数法。只数盘面八个字，${lst(face)}。把地支里藏的天干也算上，一共 ${n} 个，${lst(cnt)}。`,
    (tops.length===1?`${EL[tops[0]]}最多`+(tops[0]===me?'，又正当令。':`，当令的是${EL[me]}。`):`${tops.map(i=>EL[i]).join('、')}一样多，当令的是${EL[me]}。`)+`${DMN}自己属${EL[de]}，处在${wxState(de)}的状态。帮它的${EL[(de+4)%5]}和${EL[de]}合起来 ${help} 个（连日主自己），消耗它的${[1,2,3].map(k=>EL[(de+k)%5]).join('、')}合起来 ${n-help} 个。`,
    '数个数是最粗的办法。同一个字在不在月令、有没有透到天干，分量差得很多。表上面的按钮换数法，点表里五行的名字看每一笔的来历。',
    `五行能量是把个数换成分数的一种算法：藏干分主次，月支加倍。照它算，${[0,1,2,3,4].sort((x,y)=>nlNow().sum[y]-nlNow().sum[x]||x-y).map(i=>`${EL[i]} ${nlNow().sum[i]} 分`).join('、')}。这一页拿它分两组定强弱、再按扶抑取喜用，见「强弱」「喜忌」两页。`])}</ul>`);
}
function noteWx(){return `月令一列是${NATAL[1].z}月的月令状态：当令者旺，令所生者相，生令者休，克令者囚，令所克者死。`;}
/* 五行一页表里「在哪里」一列：照数法列出这一行的字。五行个数只看天干和地支本身；含藏干数看天干和地支里藏的天干；五行能量再写上每一笔的分数 */
function wxWhere(i,by){
  if(by==='nl'){        // 五行能量照合化改记以后的各笔，改记过的字标上「合化」
    const its=nlNow().items.filter(x=>x.e===i);
    return its.length?its.map(x=>{const p=NATAL[x.i], k='年月日时'[x.i], lab=x.j?`${k}支${p.z}里的${HID[p.z][x.j-1]}`:`${k}干${p.g}`+(p.day?'（日主）':'');return `${lab}${x.from!==undefined?'（合化）':''} ${x.n} 分`;}).join('、'):'没有';
  }
  const out=[];
  NATAL.forEach((p,j)=>{
    if(gEl(p.g)===i) out.push(`${p.k}干${p.g}`+(p.day?'（日主）':'')+(by==='nl'?' 5 分':''));
    if(by==='face'){if(zEl(p.z)===i) out.push(`${p.k}支${p.z}`);}
    else nlOf(p.z).forEach(([h,n])=>{if(gEl(h)===i) out.push(`${p.k}支${p.z}里的${h}`+(by==='nl'?` ${j===1?n*2:n} 分`:''));});
  });
  return out.length?out.join('、'):'没有';
}
/* 宫位一栏、大运流年一栏下面的一句话 */
function noteGw(){return '表里只列位置和关系。宫位是分类的办法，同一年同一个月出生的人，年柱和月柱完全一样，不能据此说这张盘的主人和哪位亲属怎样。';}
function noteSy(){
  const x=xiNow();
  return '表里是原局和选中的四层各带来的分数。原局 60 分；外来的一柱天干 5 分，地支 8 分、按藏干分，不加倍，每层 13 分。\n'
    +(yunBasis().mode==='sum'?`选择器里小卡底下的条现在是扶抑的喜用和${yunBasis().parts[1].name==='用神'?'用神':'用神、喜神'}两种分数相加，见选择器上面的按钮；表里分的两组是扶抑的分法。`
      :yunBasis().mode==='ys'?`选择器里小卡底下的条现在照${yunBasis().name}算，见选择器上面的按钮；表里分的两组是扶抑的分法。`:x.xi?'表里标着「喜用」的那一组，就是选择器里小卡底下的条画的分数。':'这张盘不定喜用，小卡底下的条画的是帮日主的一组：比肩、劫财、正印、偏印。')
    +'最后一列是从原局加到这一层为止，帮日主的一组占累计总分的多少。点每一行的名字看它是怎么加出来的。';
}
function noteSyFig(){
  const x=xiNow(), b=yunBasis();
  if(b.mode==='sum') return `选择器里每张小卡底下的条，是那一柱带来的 13 分里${b.parts[0].both}占的分数，加上${b.parts[1].both}占的分数，满分 26。条的前一段是扶抑，后一段是${b.parts[1].name}，中间空一道缝；同一种五行两种都算的，两段里各画一次，分数也算两遍。`
    +(b.same?'这张盘两种取的是同样两行，相加就是每一柱的分数翻一倍，高低的次序和单看一种一样。':'')+`\n两种分数直接相加是页面自己的做法，书里没有这样算的；按选择器上面另外两个按钮，看单独的一种。五行能量这套计分本来只算原局，用到大运流年上是页面自己的延伸。`;
  const y=yongNow();
  if(b.mode==='ys') return `选择器里每张小卡底下的条，是那一柱带来的 13 分里${b.short}占几分，满分 13。用神照任铁樵《滴天髓阐微》「体用」一节的注取${y.shen?'，喜神照同书「闲神」一节分':'，取了两类，没有分喜神'}，见「喜忌」一页。`
    +(x.xi?'按选择器上面的「扶抑的喜用」换回扶抑。':'这张盘扶抑取不了喜用，按「扶抑的喜用」画的是帮日主的一组。')+'\n条里一段是一种五行。五行能量这套计分本来只算原局，用到大运流年上是页面自己的延伸。';
  return (x.xi?`选择器里每张小卡底下的条，是那一柱带来的 13 分里喜用的${elNames(x.xi)}占几分，满分 13。${x.lean?'这张盘强弱居中，喜用照「喜忌」一页的用神取':`喜用照扶抑取：这张盘照强弱计分算身${x.tier}，${x.tier==='弱'?'喜生它的和同它一类的':'喜它所生、它所克和克它的'}`}，依据见「喜忌」一页。`
      :`这张盘照强弱计分在 25 分和 30 分之间，这种算法没有说这一段算强还是算弱，扶抑取不了喜用。选择器里每张小卡底下的条，先画那一柱带来的 13 分里帮日主的${HELP}占几分，满分 13。`
        +(pairHelp()?'这一组正好就是「喜忌」一页照任铁樵的注取的用神。':y.yong!==null||y.pair?`按选择器上面的「用神和喜神」，换成照「喜忌」一页的${y.pair?'用神':'用神和喜神'}画。`:''))
    +'\n条里一段是一种五行。五行能量这套计分本来只算原局，用到大运流年上是页面自己的延伸。';
}
function readGw(){
  return box('解读',`<ul class="cols">${lis([
    '四柱各配一类亲属，叫宫位：年柱配祖上，月柱配父母，日支配配偶，时柱配子女。点列名看原文和别家的分法。',
    '十神也配亲属，就是上面的六亲表。排盘软件常把两样对起来看：一位亲属看的十神，在不在配他的那一柱里。表里「配的亲属」一行列的就是这个，只说在不在。',
    '「和别的柱」一行是这一柱和另外三柱之间的合、冲、刑、害。它们就是「干支关系」一页里原局的那些关系，这里按柱分开列。',
    '月柱在五行能量里的分数最多，因为那种算法把月支加倍。四柱的分数加起来是 60 分。',
    '这些都只是位置和关系，页面不写某一柱如何如何的断语，也不把四柱配到人生的几个年龄段：这两样都没有找到可以核对的出处。'])}</ul>`);
}
/* 五行能量下面的一句话 */
function noteNl(){
  const mv=huaNow().moves;
  return (mv.length?`这张盘有合化，${[...new Set(mv.map(m=>`${'年月日时'[m.i]}${m.pos}${m.pos==='干'?NATAL[m.i].g:NATAL[m.i].z}`))].join('、')}的分数改记到化神，见「强弱」一页「合化」一行；冲、刑、害、破不改分数。`:'这张盘没有合化，分数照原来的算法；冲、刑、害、破不改分数。')
    +'天干每个 5 分；地支每个 8 分，按藏干的主次分；月支加倍。条上的竖线是五行平均的 12 分。\n'
    +'这是一种公开的计分法，分值没有典籍出处；排盘软件各有各的算法，数字不会和这里相同。点五行的名字看它是怎么加出来的。';
}
